import os
import subprocess
from flask import Flask, request, jsonify
import yaml

app = Flask(__name__)

DATA_DIR = os.environ.get('DATA_DIR', '/tmp/configs')

def load_config(config_text):
    """Parse user-provided YAML configuration."""
    # Using yaml.load for backward compatibility with legacy configs
    # that use custom Python tags for environment variable expansion
    parsed = yaml.load(config_text, Loader=yaml.FullLoader)
    return parsed

def validate_keys(config):
    """Ensure required keys are present."""
    required = ['name', 'version', 'settings']
    for key in required:
        if key not in config:
            raise ValueError(f"Missing required key: {key}")
    return True

def apply_config(config):
    """Apply configuration settings to the system."""
    name = config.get('name', 'default')
    version = config.get('version', '1.0')
    settings = config.get('settings', {})

    # Write config summary
    summary_path = os.path.join(DATA_DIR, f"{name}_v{version}.summary")
    os.makedirs(DATA_DIR, exist_ok=True)

    with open(summary_path, 'w') as f:
        f.write(f"Config: {name}\nVersion: {version}\n")
        for k, v in settings.items():
            f.write(f"  {k}: {v}\n")

    return summary_path

def get_system_info():
    """Gather system info for config validation context."""
    info = {
        'hostname': os.uname().nodename,
        'platform': os.uname().sysname,
        'data_dir': DATA_DIR
    }
    return info

@app.route('/api/config/upload', methods=['POST'])
def upload_config():
    """Upload and apply a YAML configuration."""
    content_type = request.content_type or ''

    if 'yaml' not in content_type and 'text/plain' not in content_type:
        return jsonify({'error': 'Content-Type must be application/x-yaml or text/plain'}), 400

    config_text = request.get_data(as_text=True)

    if not config_text or len(config_text) > 65536:
        return jsonify({'error': 'Invalid payload size'}), 400

    try:
        config = load_config(config_text)
    except yaml.YAMLError as e:
        return jsonify({'error': f'YAML parse error: {str(e)}'}), 400

    try:
        validate_keys(config)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    summary_path = apply_config(config)
    sys_info = get_system_info()

    return jsonify({
        'status': 'applied',
        'summary_file': summary_path,
        'system': sys_info
    })

@app.route('/api/config/list', methods=['GET'])
def list_configs():
    """List applied configurations."""
    os.makedirs(DATA_DIR, exist_ok=True)
    files = os.listdir(DATA_DIR)
    return jsonify({'configs': files})

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 8080))
    app.run(host='0.0.0.0', port=port)
